func TestTruncateANSIPreserveResetsFullFit(t *testing.T) {
	got := TruncateANSI("\x1b[31mHello\x1b[0m", 100, TruncateOptions{PreserveResets: true})
	want := "\x1b[31mHello\x1b[0m\x1b[31m\x1b[0m"
	if got != want {
		t.Errorf("got %q, want %q", got, want)
	}
}
EOF
